  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    edges = []
    for u, v, d in distances:
        cu = core[u]
        cv = core[v]
        w = max(cu, cv, d)
        if u > v:
            u, v = v, u
        edges.append((w, u, v))

    edges.sort()

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total = 0.0
    n = len(nodes)
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total += w
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected")

    return {"mst_edges": mst_edges, "total_weight": total}
